'use client'

import * as React from 'react'
import { cn, progressMachine } from "@/lib/utils"

import { useMachine } from '../hooks/use-machine'

const Progress = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & { value?: number | null; max?: number }
>(({ className, value, max = 100, ...props }, ref) => {
  const [state, send] = useMachine(progressMachine, {
    context: {
      value,
      max,
    },
  })

  // Computed percent logic in machine or here?
  // Machine has computed.percent but simple math here is fine too.
  const percent =
    state.context.value != null ? Math.round((state.context.value / state.context.max) * 100) : 0

  React.useEffect(() => {
    if (value !== undefined && value !== state.context.value) {
      send({ type: 'VALUE.SET', value })
    }
  }, [value, send, state.context.value])

  return (
    <div
      ref={ref}
      role="progressbar"
      aria-valuemax={max}
      aria-valuemin={0}
      aria-valuenow={value ?? undefined}
      data-max={max}
      data-value={value}
      data-state={state.context.value === null ? 'indeterminate' : 'loading'}
      className={cn('relative h-2 w-full overflow-hidden rounded-full bg-primary/20', className)}
      {...props}
    >
      <div
        data-slot="progress-indicator"
        className="h-full w-full flex-1 bg-primary transition-all"
        style={{ transform: `translateX(-${100 - (value || 0)}%)` }}
      />
    </div>
  )
})
Progress.displayName = 'Progress'

export { Progress }

import { normalizeProps, useMachine } from '@zag-js/vue'
import { progressConnect, progressMachine } from "@/lib/utils"
import { computed, watch } from 'vue'

export type UseProgressProps = {
    modelValue?: number | null
    max?: number
}

export function useProgress(props: UseProgressProps) {
    const machineProps = computed(() => ({
        value: props.modelValue ?? null,
        max: props.max ?? 100,
    }))

    const service = useMachine(progressMachine, machineProps)
    const api = computed(() => progressConnect(service, normalizeProps))

    watch(
        () => props.modelValue,
        (val) => {
            if (val !== undefined && val !== api.value.value) {
                api.value.setValue(val)
            }
        },
    )

    return api
}

// @ts-nocheck
import { setupProgressMachine, connectProgressMachine, type WeappProgressApi, type WeappProgressService } from './use-progress'
import { resolveClasses } from '../utils'
import { progressRootVariants, progressIndicatorVariants } from '../utils'

type WeappProgressInternal = WechatMiniprogram.Component.InstanceMethods<{}> & {
  _service?: WeappProgressService
  _cleanup?: () => void
  _send?: (event: object) => void
  data: {
    api: WeappProgressApi
  }
  properties: {
    value: number
    max: number
    min: number
    id: string
    extClass: string
  }
}

Component({
  options: {
    styleIsolation: 'apply-shared',
    pureDataPattern: /^_/,
  },

  properties: {
    value: {
      type: Number,
      value: 0,
    },
    max: {
      type: Number,
      value: 100,
    },
    min: {
      type: Number,
      value: 0,
    },
    id: {
      type: String,
      value: 'progress',
    },
    extClass: {
      type: String,
      value: '',
    },
  },

  data: {
    api: {} as WeappProgressApi,
    rootClass: '',
    indicatorClass: '',
  },

  lifetimes: {
    attached() {
      const self = this as WeappProgressInternal
      const controller = setupProgressMachine(this, {
        id: this.properties.id,
        value: this.properties.value,
        max: this.properties.max,
        min: this.properties.min,
      })

      self._service = controller.service as WeappProgressService
      self._cleanup = controller.start()
      self._send = controller.send as (event: object) => void
    },
    detached() {
      const self = this as WeappProgressInternal
      self._cleanup?.()
    },
  },

  observers: {
    'state': function (state) {
      const self = this as WeappProgressInternal
      if (!state || !self._send) return
      const api = connectProgressMachine(state, self._send) as WeappProgressApi

      const { baseClass: rootClass } = resolveClasses(progressRootVariants(), self.properties.extClass)
      const { baseClass: indicatorClass } = resolveClasses(progressIndicatorVariants())

      this.setData({ api, rootClass, indicatorClass })
    },

    'value': function (val) {
      const self = this as WeappProgressInternal
      if (self._service) {
        self._service.setContext({ value: val })
      }
    },

    'max': function (val) {
      const self = this as WeappProgressInternal
      if (self._service) {
        self._service.setContext({ max: val })
      }
    },

    'min': function (val) {
      const self = this as WeappProgressInternal
      if (self._service) {
        self._service.setContext({ min: val })
      }
    },
  },
})
